INSERT INTO products (name, slug, description, short_description, category_id, brand_id, sku, price, compare_at_price, images, primary_image, specifications, features, whats_included, compatibility, tags, rating, review_count, stock, is_featured, is_bestseller, is_new_arrival, is_deal, weight) VALUES
('Arduino Uno R3 Development Board', 'arduino-uno-r3', 'The Arduino Uno R3 is a microcontroller board based on the ATmega328P. It has 14 digital input/output pins, 6 analog inputs, a 16 MHz quartz crystal, USB connection, power jack, ICSP header, and reset button.', 'Official Arduino Uno R3 with ATmega328P microcontroller', (SELECT id FROM categories WHERE slug='arduino'), (SELECT id FROM brands WHERE slug='arduino'), 'ARD-UNO-R3', 1299.00, 1599.00, ARRAY['https://images.pexels.com/photos/15470542/pexels-photo-15470542.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/15470542/pexels-photo-15470542.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"ATmega328P","Operating Voltage":"5V","Input Voltage (recommended)":"7-12V","Digital I/O Pins":"14 (of which 6 provide PWM output)","Analog Input Pins":"6","Flash Memory":"32 KB","SRAM":"2 KB","EEPROM":"1 KB","Clock Speed":"16 MHz","Length":"68.6 mm","Width":"53.4 mm","Weight":"25 g"}'::jsonb, ARRAY['Open-source programmable board','USB connectivity','14 digital I/O pins','6 analog inputs','16 MHz clock speed'], ARRAY['1x Arduino Uno R3 Board','1x USB A-to-B cable'], ARRAY['Arduino IDE','Arduino Web Editor','Most Arduino shields'], ARRAY['arduino','uno','development board','microcontroller','atmega328p','beginner'], 4.8, 342, 150, true, true, false, true, 25),
('Raspberry Pi 4 Model B 4GB RAM', 'raspberry-pi-4-model-b-4gb', 'The Raspberry Pi 4 Model B is the latest version of the popular single-board computer. Featuring a quad-core 64-bit ARM Cortex-A72 CPU, 4GB LPDDR4 RAM, dual micro-HDMI ports, USB 3.0, Gigabit Ethernet, and dual-band Wi-Fi.', 'Quad-core 64-bit ARM CPU with 4GB RAM', (SELECT id FROM categories WHERE slug='raspberry-pi'), (SELECT id FROM brands WHERE slug='raspberry-pi'), 'RP-PI4-4GB', 5499.00, 6499.00, ARRAY['https://images.pexels.com/photos/7097230/pexels-photo-7097230.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/1432794/pexels-photo-1432794.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/28675583/pexels-photo-28675583.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/7097230/pexels-photo-7097230.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"CPU":"Broadcom BCM2711, Quad core Cortex-A72 @ 1.5GHz","RAM":"4GB LPDDR4-3200","Networking":"Gigabit Ethernet, 2.4GHz and 5GHz 802.11ac","Bluetooth":"Bluetooth 5.0","Video Output":"2x micro-HDMI (up to 4Kp60)","USB":"2x USB 3.0, 2x USB 2.0","GPIO":"40-pin","Power":"5V DC via USB-C","Dimensions":"88 x 56 x 19 mm"}'::jsonb, ARRAY['Quad-core 64-bit CPU','4GB LPDDR4 RAM','4K video output','Gigabit Ethernet','Dual-band Wi-Fi','Bluetooth 5.0'], ARRAY['1x Raspberry Pi 4 Model B'], ARRAY['Raspberry Pi OS','Ubuntu','Kodi','RetroPie'], ARRAY['raspberry pi','sbc','single board computer','linux','iot','media center'], 4.9, 521, 85, true, true, false, true, 46),
('ESP32 DevKit V1 Development Board', 'esp32-devkit-v1', 'The ESP32 DevKit V1 is a powerful Wi-Fi + Bluetooth dual-core microcontroller development board. With 520KB SRAM, dual-core 240MHz CPU, and rich peripheral set, it is perfect for IoT applications.', 'Dual-core Wi-Fi + Bluetooth microcontroller board', (SELECT id FROM categories WHERE slug='esp32-esp8266'), (SELECT id FROM brands WHERE slug='espressif'), 'ESP-DEVKIT-V1', 599.00, 899.00, ARRAY['https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"ESP32-D0WDQ6","CPU":"Xtensa dual-core 32-bit LX6","Clock Speed":"240 MHz","Flash Memory":"4 MB","SRAM":"520 KB","Wi-Fi":"802.11 b/g/n","Bluetooth":"v4.2 BR/EDR and BLE","Operating Voltage":"3.3V","Input Voltage":"7-12V","Digital I/O Pins":"30","Analog Input Pins":"8","Dimensions":"51 x 28 mm"}'::jsonb, ARRAY['Dual-core 240MHz CPU','Wi-Fi + Bluetooth','4MB Flash','30 digital I/O pins','8 analog inputs','Low power modes'], ARRAY['1x ESP32 DevKit V1 Board'], ARRAY['Arduino IDE','PlatformIO','ESP-IDF','MicroPython'], ARRAY['esp32','wifi','bluetooth','iot','microcontroller','dual-core'], 4.7, 218, 200, true, true, true, false, 10),
('Arduino Mega 2560 R3 Development Board', 'arduino-mega-2560-r3', 'The Arduino Mega 2560 is a microcontroller board based on the ATmega2560. With 54 digital I/O pins, 16 analog inputs, 256KB flash, and 8KB SRAM, it is ideal for complex projects requiring many I/O pins.', 'ATmega2560 board with 54 digital I/O pins', (SELECT id FROM categories WHERE slug='arduino'), (SELECT id FROM brands WHERE slug='arduino'), 'ARD-MEGA-2560', 2199.00, 2799.00, ARRAY['https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/15470542/pexels-photo-15470542.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"ATmega2560","Operating Voltage":"5V","Input Voltage":"7-12V","Digital I/O Pins":"54 (15 PWM)","Analog Input Pins":"16","Flash Memory":"256 KB","SRAM":"8 KB","EEPROM":"4 KB","Clock Speed":"16 MHz","Length":"101.5 mm","Width":"53.3 mm","Weight":"37 g"}'::jsonb, ARRAY['54 digital I/O pins','16 analog inputs','256KB flash','8KB SRAM','16 MHz clock'], ARRAY['1x Arduino Mega 2560 R3','1x USB A-to-B cable'], ARRAY['Arduino IDE','Most Arduino shields'], ARRAY['arduino','mega','2560','microcontroller','development board'], 4.8, 178, 90, true, true, false, false, 37),
('Arduino Nano V3.0 Development Board', 'arduino-nano-v3', 'The Arduino Nano is a compact, breadboard-friendly microcontroller board based on the ATmega328P. Features 14 digital I/O pins, 8 analog inputs, and a mini-B USB port. Perfect for small projects and embedded applications.', 'Compact ATmega328P board for breadboards', (SELECT id FROM categories WHERE slug='arduino'), (SELECT id FROM brands WHERE slug='arduino'), 'ARD-NANO-V3', 899.00, 1199.00, ARRAY['https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"ATmega328P","Operating Voltage":"5V","Input Voltage":"7-12V","Digital I/O Pins":"14 (6 PWM)","Analog Input Pins":"8","Flash Memory":"32 KB","SRAM":"2 KB","EEPROM":"1 KB","Clock Speed":"16 MHz","Dimensions":"45 x 18 mm","Weight":"7 g"}'::jsonb, ARRAY['Compact breadboard-friendly design','14 digital I/O pins','8 analog inputs','Mini-B USB','16 MHz clock'], ARRAY['1x Arduino Nano V3','1x Mini-B USB cable'], ARRAY['Arduino IDE','Arduino Web Editor'], ARRAY['arduino','nano','compact','microcontroller','breadboard'], 4.7, 134, 180, false, true, false, false, 7),
('NodeMCU ESP8266 WiFi Development Board', 'nodemcu-esp8266-wifi', 'The NodeMCU ESP8266 is an open-source Lua-based firmware development board with WiFi capability. Features the ESP-12E module with 4MB flash, 80MHz clock, and built-in WiFi.', 'WiFi-enabled development board with ESP-12E', (SELECT id FROM categories WHERE slug='esp32-esp8266'), (SELECT id FROM brands WHERE slug='nodemcu'), 'ESP-NODEMCU-V3', 349.00, 599.00, ARRAY['https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"ESP-12E (ESP8266)","CPU":"Tensilica L106 32-bit","Clock Speed":"80 MHz (max 160 MHz)","Flash Memory":"4 MB","RAM":"50 KB","Wi-Fi":"802.11 b/g/n","Operating Voltage":"3.3V","Input Voltage":"7-12V","Digital I/O Pins":"11","Analog Input Pins":"1","Dimensions":"51 x 28 mm"}'::jsonb, ARRAY['Built-in WiFi','4MB Flash','Arduino IDE compatible','MicroPython support','Low cost'], ARRAY['1x NodeMCU ESP8266 Board','1x Micro USB cable'], ARRAY['Arduino IDE','PlatformIO','MicroPython','Lua'], ARRAY['esp8266','nodemcu','wifi','iot','development board'], 4.4, 145, 250, false, true, false, false, 10),
('ESP32-CAM Camera Development Board', 'esp32-cam-module', 'The ESP32-CAM is a development board with an integrated OV2640 camera and microSD card slot. Features Wi-Fi and Bluetooth connectivity, making it perfect for IoT camera projects, video streaming, and face recognition.', 'ESP32 with OV2640 camera and microSD slot', (SELECT id FROM categories WHERE slug='esp32-esp8266'), (SELECT id FROM brands WHERE slug='espressif'), 'ESP-CAM-V1', 599.00, 899.00, ARRAY['https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"ESP32-D0WD","CPU":"Dual-core 32-bit LX6 @ 240MHz","Flash":"4MB","Camera":"OV2640 (2MP)","Resolution":"1600x1200 max","Wi-Fi":"802.11 b/g/n","Bluetooth":"v4.2 BR/EDR + BLE","Storage":"MicroSD card slot","Operating Voltage":"5V","Dimensions":"40 x 27 x 10 mm"}'::jsonb, ARRAY['Integrated OV2640 camera','Wi-Fi + Bluetooth','MicroSD card slot','Face recognition support','Video streaming capable'], ARRAY['1x ESP32-CAM Board','1x OV2640 Camera Module','1x Antenna'], ARRAY['Arduino IDE','ESP-IDF','PlatformIO'], ARRAY['esp32','camera','wifi','iot','video streaming','ai'], 4.4, 123, 180, true, false, true, true, 15),
('ESP8266 ESP-01 WiFi Module', 'esp8266-esp-01-wifi', 'The ESP-01 is a minimal WiFi module based on the ESP8266 chip. Features 2 GPIO pins, 1MB flash, and AT firmware. Perfect for adding WiFi to existing Arduino projects with minimal cost.', 'Minimal ESP8266 WiFi module with AT firmware', (SELECT id FROM categories WHERE slug='esp32-esp8266'), (SELECT id FROM brands WHERE slug='espressif'), 'ESP-01-WIFI', 99.00, 179.00, ARRAY['https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Chip":"ESP8266","Flash":"1 MB","Wi-Fi":"802.11 b/g/n","Operating Voltage":"3.3V","Digital I/O":"2","Serial":"UART (AT commands)","Antenna":"PCB trace","Dimensions":"14.3 x 24.8 mm","Weight":"2 g"}'::jsonb, ARRAY['Minimal WiFi module','AT firmware included','2 GPIO pins','3.3V operation','Ultra-low cost'], ARRAY['1x ESP-01 Module','1x 2x4 header pins'], ARRAY['Arduino (via serial)','ESP8266 toolchain'], ARRAY['esp8266','esp-01','wifi','module','iot','cheap'], 4.2, 78, 400, false, false, false, true, 2),
('Raspberry Pi Pico RP2040 Microcontroller Board', 'raspberry-pi-pico', 'The Raspberry Pi Pico is a low-cost, high-performance microcontroller board built around the RP2040 chip. Features dual-core ARM Cortex-M0+ CPU, 264KB SRAM, 2MB flash, and 26 GPIO pins. Programmable in C/C++ and MicroPython.', 'RP2040 dual-core microcontroller board', (SELECT id FROM categories WHERE slug='development-boards'), (SELECT id FROM brands WHERE slug='raspberry-pi'), 'RP-PICO', 449.00, 599.00, ARRAY['https://images.pexels.com/photos/7097230/pexels-photo-7097230.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/7097230/pexels-photo-7097230.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Microcontroller":"RP2040","CPU":"Dual-core ARM Cortex-M0+ @ 133MHz","Flash":"2MB external QSPI","SRAM":"264KB","GPIO":"26 pins","PWM Channels":"16","ADC Channels":"4","Interface":"USB 1.1","Dimensions":"51 x 21 mm","Weight":"3 g"}'::jsonb, ARRAY['Dual-core 133MHz CPU','264KB SRAM','2MB flash','26 GPIO pins','Programmable in C/C++ and MicroPython','Low cost'], ARRAY['1x Raspberry Pi Pico'], ARRAY['MicroPython','C/C++ SDK','Arduino IDE (via community core)'], ARRAY['raspberry pi','pico','rp2040','microcontroller','dual core','micropython'], 4.7, 156, 300, true, true, true, false, 3)
